# -*- coding: utf-8 -*-
"""generate 후 수동 audioSummary(3열+ 표)를 script.json에 재주입하는 검수 보조 도구.

generate(build_script_json)는 parse_segments부터 새로 만들어 수동 audioSummary를
덮어쓴다. 따라서 수동 요약은 이 스크립트의 SUMMARIES에 SSOT로 두고,
`lexicon 갱신 → generate → apply_audio_summary → gate` 순서로 재주입한다.

- 2열 표 자동초벌(table-summary-draft)은 generate가 채우므로 여기 넣지 않는다.
- audioSummary 텍스트는 generate의 apply_lexicon을 거치지 않으므로, 약어는
  최종 한글 발음으로 직접 쓴다(예: AWS→에이더블유에스).
- 검수 전 산출물. script.json은 approved 전까지 repo/pubspec 등록 금지.

사용: py tool/apply_audio_summary.py [doc-id ...]   (생략 시 SUMMARIES 전체)
"""
import json
import sys
from pathlib import Path

sys.stdout.reconfigure(encoding="utf-8")

BASE = Path(__file__).resolve().parent.parent  # flutter_app/


def _cert_dir(doc_id: str) -> Path:
    """doc_id 접두어(clf/saa/soa …)로 자격증 오디오 디렉터리 파생.
    doc_id는 자격증 접두어가 붙어 전역 유일하다(예: saa-t1-1 → assets/audio/saa)."""
    cert = doc_id.split("-", 1)[0]
    return BASE / "assets" / "audio" / cert

